'use strict';

// Estado de versión: número en la barra superior y en Ajustes > Versión (rojo si estás atrasado, verde si es la última).
const WCUpdate = (() => {
  let res = null; // último resultado de update:check
  let version = '';
  let lastCheck = 0;

  // Historial: [versión, es, en]
  const CHANGELOG = [
    ['1.0.14', 'Daño recibido: al pulsar un jugador se ve el daño que recibió de cada habilidad (golpes y ticks) y de qué fuente venía (jefe, adds, entorno), en vez de su rotación y su daño.', 'Damage taken: clicking a player now shows the damage they took from each ability (hits and ticks) and which source it came from (boss, adds, environment), instead of their rotation and damage.'],
    ['1.0.13', 'Daño recibido: el desplegable de habilidades muestra el icono de cada habilidad y, al pasar el ratón junto al icono, su tooltip.', 'Damage taken: the ability dropdown shows each ability’s icon and, hovering next to the icon, its tooltip.'],
    ['1.0.12', 'Daño evitable: «Quién recibió más daño evitable» muestra el icono de especialización junto a cada nombre en lugar del punto de color.', 'Avoidable damage: «Who took the most avoidable damage» shows the spec icon next to each name instead of the colored dot.'],
    ['1.0.11', 'Lista de pulls: cada try muestra entre «Try N» y el porcentaje la hora (24 h, sin segundos) a la que acabó.', 'Pull list: each try shows the time it ended (24 h, no seconds) between «Try N» and the percentage.'],
    ['1.0.10', 'Portada: el botón «Comparar logs» es ahora una copia exacta del desplegable «Todas las regiones» del buscador de personajes: mismo fondo, borde, esquinas, tamaño y letra, y el mismo efecto al pasar el ratón (sube 1 px con borde de acento y halo suave).', 'Home: the «Compare logs» button is now an exact copy of the «All regions» dropdown of the character search: same background, border, corners, size and font, and the same hover effect (it rises 1 px with an accent border and a soft halo).'],
    ['1.0.9', 'Parche 12.1.5: al pulsar «Contenido del 12.1.5» se abre el tráiler oficial dentro de la propia ventana, sin salir a YouTube: en castellano si WipeTime está en español y en inglés si está en inglés.', 'Patch 12.1.5: clicking «12.1.5 content» opens the official trailer inside the window itself, without leaving for YouTube: in Spanish when WipeTime is in Spanish and in English when it is in English.'],
    ['1.0.8', 'Portada: el botón «Comparar logs» pasa a tener el mismo efecto al pasar el ratón que el desplegable «Todas las regiones» del buscador de personajes (sube un poco, borde de acento y halo suave).', 'Home: the «Compare logs» button now has the same hover effect as the «All regions» dropdown of the character search (it rises slightly, with an accent border and a soft halo).'],
    ['1.0.7', 'Portada: el botón «Comparar logs» tiene ahora el mismo efecto al pasar el ratón que las tarjetas y botones de abajo (se eleva, borde y halo de luz, brillo que lo cruza y el icono se inclina).', 'Home: the «Compare logs» button now has the same hover effect as the cards and buttons below (it lifts, with a light border and halo, a sweeping shine and a tilting icon).'],
    ['1.0.6', 'Cambios de las clases: las entradas que decían solo «Correcciones varias» o «Correcciones de…» ahora explican qué se corrigió exactamente (por ejemplo, Wild Guardian aumentaba el daño de Thrash y Mangle sin tener el rango 3, o los ajustes de PvP de Celestial Conduit y Flurry Strikes se aplicaban también en PvE), tomado del registro oficial de hotfixes de Blizzard. Cambian de idioma con la web.', 'Class changes: entries that only said «Assorted fixes» or «Fixes to…» now explain exactly what was fixed (for example, Wild Guardian was increasing Thrash and Mangle damage without Rank 3, or the PvP adjustments to Celestial Conduit and Flurry Strikes were also applying in PvE), taken from Blizzard official hotfix log. They change language with the web.'],
    ['1.0.5', 'Inicio: efecto al pasar el ratón como el de NinjaLoot, en el color de acento de WipeTime: las tarjetas de funciones y los reportes recientes se elevan con un halo de luz y un brillo que las cruza, el icono se inclina, y el buscador de personajes, su desplegable y sus botones pequeños se iluminan al acercarte.', 'Home: hover effect like the one in NinjaLoot, in the WipeTime accent color: the feature cards and recent reports lift with a light halo and a sweeping shine, the icon tilts, and the character search, its dropdown and small buttons light up as you hover.'],
    ['1.0.4', 'Informe general: nuevo apartado «Chivato» con las pociones de salud y las piedras de salud que ha usado cada jugador en todos los intentos de boss de la noche, cada una por separado y con el total de la banda. Salen también los jugadores que no han usado ninguna.', 'General report: new «Snitch» section with the health potions and healthstones each player used across every boss pull of the night, listed separately with the raid total. Players who used none are listed too.'],
    ['1.0.3', 'Barra superior con el estilo de NinjaLoot: botones de navegación sin caja, el activo con fondo suave y línea de acento. El botón «Idioma» va en singular y «Exportar» solo aparece con un reporte abierto. El círculo del reloj gira una vuelta cada 24 horas (ya no por segundos) y la portada tiene aurora y borde de luz en movimiento con el color de acento. Cambios de las clases: nombres de habilidades, talentos de héroe y la banda en el idioma de la web, y descripciones de Wowhead en ese idioma para las 300 habilidades (antes algunas salían sin descripción o en inglés).', 'Top bar restyled like NinjaLoot: navigation buttons without a box, the active one with a soft background and an accent line. The language button now reads «Language» and «Export» only appears with a report open. The clock circle makes one turn every 24 hours (no longer per second) and the home panel gets a moving aurora and light border in the accent color. Class changes: ability, hero talent and raid names in the web language, and Wowhead descriptions in that language for all 300 abilities (some used to appear without a description or in English).'],
    ['1.0.2', 'Reloj del servidor: ya se ve bien (los segundos chocaban con el estilo de las marcas de tiempo del replay) y pasa a la derecha del logo de WipeTime. Cambios de las clases: cada especialización es ahora un desplegable cerrado que se abre al pulsarla, y la lista se desplaza con la rueda del ratón cuando hay muchos cambios. Añadidas 47 correcciones y cambios menores del registro oficial de hotfixes de Blizzard (13 de agosto – 14 de octubre) que faltaban, incluidas las de Paladín Sagrado.', 'Server clock: now displays correctly (the seconds clashed with the replay timeline tick style) and moves to the right of the WipeTime logo. Class changes: each specialization is now a collapsed section that opens when clicked, and the list scrolls with the mouse wheel when there are many changes. Added 47 fixes and minor changes from Blizzard\x27s official hotfix log (August 13 – October 14) that were missing, including Holy Paladin ones.'],
    ['1.0.1', 'Corregido el arranque: la 1.0.0 podía quedarse sin cargar por el orden en que se iniciaba el reloj del servidor. El reloj pasa al extremo izquierdo de la barra superior.', 'Startup fix: 1.0.0 could fail to load because of the order in which the server clock started. The clock moves to the far left of the top bar.'],
    ['1.0.0', 'Cambios de clase: botón propio bajo el del parche 12.2 con todos los cambios de PvE del 12.1.0 al 12.1.5 por clase y especialización (con iconos y fecha exacta; verde = mejora, rojo = nerfeo). Los nombres de habilidades salen en el idioma de la app y cada uno tiene su tooltip. Reloj del servidor arriba a la izquierda (Europa por defecto; América, Latinoamérica, Oceanía, Corea y Taiwán en Ajustes → Apariencia) y, al pasar el ratón, cuenta atrás hasta el reinicio semanal. Las tarjetas del inicio ya no se pueden seleccionar.', 'Class changes: its own button under the 12.2 one with every PvE change from 12.1.0 to 12.1.5 by class and specialization (with icons and exact date; green = buff, red = nerf). Ability names appear in the app language and each has its tooltip. Server clock at the top left (Europe by default; Americas, Latin America, Oceania, Korea and Taiwan in Settings → Appearance) and, on hover, a countdown to the weekly reset. The home cards can no longer be selected.'],
    ['0.9.5', 'Nuevo apartado «Cambios de las clases» en el inicio: todos los cambios de PvE por clase y especialización (con sus iconos) del parche 12.1.0 al 12.1.5, cada uno con su fecha exacta; en verde las mejoras y en rojo los nerfeos. Botones con brillo y elevación al pasar el ratón, y el botón del parche 12.1.5 y la etiqueta «Próximamente» ahora están animados.', 'New «Class changes» section on the home screen: every PvE change by class and specialization (with their icons) from patch 12.1.0 to 12.1.5, each with its exact date; buffs in green and nerfs in red. Buttons shine and lift on hover, and the 12.1.5 patch button and the “Coming soon” tag are now animated.'],
    ['0.9.4', 'Inicio: nuevo botón «Parche 12.2 · Próximamente» bajo el del 12.1.5. Abre un panel con lo que muestra el avance de Midnight: Eclipse (anunciado por Warcraft ES el 15 de octubre): una nueva zona, la mazmorra de tres jefes Bastión de Thraegar, la banda de ocho jefes El Núcleo del Mundo y la nueva daga legendaria Filo de Medianoche, con las imágenes del avance y el enlace al anuncio. Blizzard aún no ha dado fecha de salida.', 'Home: new «Patch 12.2 · Coming soon» button under the 12.1.5 one. It opens a panel with what the Midnight: Eclipse preview shows (announced by Warcraft ES on October 15): a new zone, the three-boss dungeon Thraegar’s Bastion, the eight-boss raid The World’s Core and the new legendary dagger Midnight’s Edge, with the preview images and a link to the announcement. Blizzard has not given a release date yet.'],
    ['0.9.3', 'Las habilidades que Warcraft Logs no nombra («Unknown Ability») salen ahora como «Habilidad desconocida» en el motivo del wipe y en los resúmenes. Modo silencioso interno para pruebas (variable WIPETIME_QUIET): no cambia nada para el usuario.', 'Abilities Warcraft Logs does not name («Unknown Ability») now show as «Unknown ability» in the wipe cause and in the summaries. Internal quiet mode for tests (WIPETIME_QUIET variable): nothing changes for users.'],
    ['0.9.2', 'Progreso: ahora se puede comparar con el intento anterior además de con tu mejor intento, con tabla de HPS por sanador y los iconos de spec. Clasificaciones (formato Warcraft Logs): botones «Copiar imagen» y «Guardar PNG» para exportar las tres tablas. Nuevo botón «Copiar resumen» junto al selector de fases: copia un resumen del intento (resultado, motivo del wipe, primeras muertes, mejores DPS y HPS y enlace) listo para pegar en Discord. La ventana ya no se desborda por debajo de unos 1300 px: los botones de la cabecera quedan solo con icono y las tablas hacen scroll por su cuenta. Los parses estimados muestran puntos mientras se calculan y no se inventa un «Ilvl %» si el jefe no tiene tramos de nivel de objeto. Kith’ix: las notas usan los nombres reales en español de los adds (Mole venenosa, Tejevacío, Alfazaque bombardero, Aguijoneamentes) y «Presencia imponente» y «Aullido estigio» quedan verificadas con un kill real. Pruebas automáticas (npm test) en cada subida.', 'Progress: you can now compare with the previous attempt as well as with your best attempt, with an HPS-per-healer table and spec icons. Rankings (Warcraft Logs format): «Copy image» and «Save PNG» buttons to export the three tables. New «Copy summary» button next to the phase selector: it copies a summary of the attempt (result, wipe cause, first deaths, top DPS and HPS and a link) ready to paste into Discord. The window no longer overflows below about 1300 px: header buttons become icon-only and tables scroll on their own. Estimated parses show dots while they are computed and no «Ilvl %» is made up when the boss has no item level brackets. Kith’ix: the notes use the real Spanish names of the adds and «Commanding Presence» and «Stygian Howl» are verified against a real kill. Automated tests (npm test) on every push.'],
    ['0.9.1', 'Replay con buffos y debuffos exactos: ahora salen de las bandas de actividad de Warcraft Logs, así que aparecen también los que ya estaban puestos antes del pull (frasco, comida, runas, Flujo de chi…), que antes se perdían. Cada aura sale una sola vez, con su nombre e icono reales y sus stacks.', 'Replay with exact buffs and debuffs: they now come from Warcraft Logs activity bands, so the ones already active before the pull (flask, food, runes, Chi Flow…) also show up, which were missed before. Each aura appears once, with its real name and icon and its stacks.'],
    ['0.9.0', 'Quitados el francés y el alemán: la app queda en español e inglés (si tenías uno de esos idiomas, vuelve al español). Parses corregidos: Warcraft Logs devuelve 0 a los jugadores con posición aproximada (~) en su modo por defecto, así que ahora se piden también en modo «Parses» y se usa ese valor, que es el que enseña la web (en un log de prueba pasaron de 8 a 14 aciertos exactos de 16). En logs recientes los parses se vuelven a pedir cada minuto y se avisa de que son provisionales, porque Warcraft Logs los ajusta durante las primeras horas.', 'French and German removed: the app is now Spanish and English only (if you had one of those languages, it goes back to Spanish). Parses fixed: Warcraft Logs returns 0 for players with an approximate position (~) in its default mode, so they are now also requested in «Parses» mode and that value is used, which is what the website shows (on a test log they went from 8 to 14 exact matches out of 16). On recent logs parses are requested again every minute and flagged as provisional, because Warcraft Logs adjusts them during the first hours.'],
    ['0.8.4', 'Clasificaciones con el formato de Warcraft Logs para el kill elegido: ranking de ejecución (muertes, daño recibido, nivel de objeto), ranking de velocidad (duración) y clasificación de jugadores con pestañas Daño, Sanación y Daño al jefe, con % de rango, rango, de cuántos, mejor rango, jugador con su servidor, DPS/HPS, Ilvl e Ilvl %. La vista anterior con varios intentos y filtros sigue disponible como «Vista avanzada».', 'Rankings in Warcraft Logs format for the chosen kill: execution ranking (deaths, damage taken, item level), speed ranking (duration) and player rankings with Damage, Healing and Boss damage tabs, with rank %, rank, out of, best rank, player with their realm, DPS/HPS, Ilvl and Ilvl %. The previous view with several pulls and filters is still available as «Advanced view».'],
    ['0.8.3', 'Quitado el icono del rayo del botón «Combinar pulls» y del aviso «Combinando N pulls».', 'Removed the lightning icon from the «Combine pulls» button and the «Combining N pulls» notice.'],
    ['0.8.2', 'Corregido el icono de spec de jugadores cuyo informe solo traía la clase (salía el icono de la clase en lugar de el de su especialización, en la elección de personaje y en las listas): ahora la spec se toma de los detalles de jugador de Warcraft Logs. El botón Actualizar ya no lleva icono.', 'Fixed the spec icon of players whose report only carried the class (the class icon showed instead of the specialization one, in the character picker and in the lists): the spec is now taken from Warcraft Logs player details. The Refresh button no longer has an icon.'],
    ['0.8.1', 'Informe general: nuevo Top 5 de dispels de la noche, junto a los de muertes, DPS, sanadores y cortes. Cuenta las disipaciones de cada jugador en todos los intentos de jefe del log.', 'General report: new Top 5 dispels of the night, next to deaths, DPS, healers and interrupts. It counts each player’s dispels across every boss attempt in the log.'],
    ['0.8.0', 'Kith’ix con su guía de mecánicas completa: 28 mecánicas repartidas en Fase 1, intermedio de Oscuridad agobiante y Fase 2, con el nombre real de cada habilidad en español, su tipo, las dificultades en las que aparece y su icono. Basada en las guías de Method, wow.gg y Skycoach; las que solo cuenta una guía salen como «sin verificar». También se corrigen los nombres de Garra abisal, Oscuridad sofocante y Eclipse que tenía antes la guía.', 'Kith’ix now has its full mechanics guide: 28 mechanics across Phase 1, the Suffocating Darkness intermission and Phase 2, with each ability real Spanish name, type, difficulties and icon. Based on the Method, wow.gg and Skycoach guides; the ones only one guide reports are shown as unverified. The names that were guessed before are also fixed.'],
    ['0.7.9', 'Parses completos como en Warcraft Logs: en Daño los sanadores también tienen su parse de daño, y en Sanación los DPS y los tanques tienen su parse de sanación (antes, en los wipes, cada rol solo mostraba el parse de su propia métrica).', 'Full parses like Warcraft Logs: in Damage the healers also get their damage parse, and in Healing the DPS and tanks get their healing parse (before, on wipes, each role only showed the parse of its own metric).'],
    ['0.7.8', 'Listas de daño, sanación y demás con el formato de Warcraft Logs: Parse %, nombre con icono de spec, cantidad con el % del total, barra del color de la clase (con el daño de mascotas en azul) y la cantidad a su lado, Ilvl, Ilvl %, Activo y DPS/HPS completos con el separador de miles de cada idioma. En el replay, al pasar el ratón por un buffo o debuff sale su tooltip con qué hace y cuánto le queda en ese momento. Prepoti y pociones con el icono de spec. Tarjeta del parche del inicio más grande.', 'Damage, healing and other lists use the Warcraft Logs format: Parse %, name with spec icon, amount with the share of the total, class-colored bar (pet damage in blue) with the amount next to it, Ilvl, Ilvl %, Active and full DPS/HPS with each language’s thousands separator. In the replay, hovering a buff or debuff shows its tooltip with what it does and how long it has left at that moment. Prepot and potions with the spec icon. Bigger patch card on the home screen.'],
    ['0.7.7', 'Identificador interno de la aplicación cambiado a com.kingkhaax.wipetime (sin datos personales); el instalador conserva su identidad anterior, así que las actualizaciones siguen funcionando. Los instaladores ya no pueden incluir claves de API dentro del programa: se usa siempre el servidor intermedio.', 'Internal application identifier changed to com.kingkhaax.wipetime (no personal data); the installer keeps its previous identity, so updates keep working. Installers can no longer bundle API keys inside the program: the intermediate server is always used.'],
    ['0.7.6', 'Todo lo que sale de un informe (parses, lista de intentos y datos de los kills) se pide siempre en vivo a Warcraft Logs, sin guardar copias en el disco. Dentro de una misma sesión se reutiliza lo ya cargado para no gastar la cuota de la API.', 'Everything that comes from a report (parses, pull list and kill data) is always requested live from Warcraft Logs, with no copies kept on disk. Within one session what is already loaded is reused so the API quota is not wasted.'],
    ['0.7.5', 'Parses: los parses de los kills se piden siempre a Warcraft Logs en el momento (antes se guardaban hasta 12 horas, y Warcraft Logs da valores provisionales al subir un log y los ajusta después, por eso podían salir más bajos que en su web). Si Warcraft Logs aún no los ha calculado, no se dan por buenos y se vuelven a pedir.', 'Parses: kill parses are now always requested from Warcraft Logs live (they used to be kept up to 12 hours, and Warcraft Logs gives provisional values right after an upload and adjusts them later, which is why they could be lower than on its website). If Warcraft Logs has not computed them yet they are not trusted and are requested again.'],
    ['0.7.4', 'Jefes de banda: la lista de jefes y zonas se refresca cada hora (antes se guardaba 7 días y tras el parche 12.1.5 seguían saliendo 9 jefes). Ahora salen los 10, con Kith’ix, en clasificaciones, perfiles y guilds. Parses: los estimados de wipes se comparan con la partición del propio log y, cuando Warcraft Logs trunca la lista de comparación (más de 2000 entradas), ya no se muestra un porcentaje falso y demasiado bajo. En kills el parse es el real de Warcraft Logs.', 'Raid bosses: the boss and zone list now refreshes every hour (it used to be kept for 7 days, so 9 bosses kept showing after patch 12.1.5). All 10 now appear, including Kith’ix, in rankings, profiles and guilds. Parses: wipe estimates are compared against the log’s own partition and, when Warcraft Logs truncates the comparison list (over 2000 entries), a false, too-low percentage is no longer shown. For kills the parse is the real Warcraft Logs one.'],
    ['0.7.3', 'Replay, marcos: los buffos y perjuicios salen exactamente como están en el log en ese instante (un icono por hechizo, sin multiplicarse y con las acumulaciones reales en cada momento; un jugador muerto no muestra ninguno). La barra de casteo solo muestra hechizos con tiempo de lanzamiento de verdad (los instantáneos ya no salen), avanza de forma fluida y, además de la del jugador, sale la del jefe (o de su objetivo) y la del aliado al mismo nivel.', 'Replay frames: buffs and debuffs now match the log exactly at that moment (one icon per spell, no duplicates, real stack counts at each instant; a dead player shows none). The cast bar only shows spells with a real cast time (instants no longer appear), moves smoothly and, besides the player, the boss (or its target) and the ally are shown at the same level.'],
    ['0.7.2', 'Replay: al pulsar un jugador sale su cono de visión en el mapa (hacia dónde mira) y, abajo, los marcos como en el replay de Warcraft Logs: el jugador con sus buffos, perjuicios, barra de vida y el hechizo que está lanzando; su objetivo (el jefe) con sus buffos, perjuicios y barra de vida; y en medio el objetivo del jefe con sus perjuicios.', 'Replay: clicking a player shows their vision cone on the map (where they are facing) and, at the bottom, unit frames like the Warcraft Logs replay: the player with their buffs, debuffs, health bar and the spell being cast; their target (the boss) with its buffs, debuffs and health bar; and in the middle the boss target with its debuffs.'],
    ['0.7.1', 'En las listas de barras, la columna de por segundo ya no pone «/s»: dice DPS en daño y daño a enemigos, HPS en sanación y DTPS en daño recibido (también en la imagen exportada).', 'In the bar lists, the per-second column no longer says «/s»: it says DPS for damage and damage to enemies, HPS for healing and DTPS for damage taken (also in the exported image).'],
    ['0.7.0', 'Arreglados los iconos rotos («?»): los iconos de las especializaciones (40) y de la interfaz ahora vienen incluidos en el programa y no dependen de la red ni del servidor de iconos de Warcraft Logs, que se bloquea a ratos en España. Si una especialización no tiene icono propio se usa el de su clase. Los iconos de habilidades que sí se descargan se piden a Wowhead y Blizzard si falla Warcraft Logs, y ante un fallo se reintentan y se pide directo al CDN antes de mostrar «?».', 'Fixed broken icons («?»): the 40 specialization icons and the interface icons are now bundled with the program and no longer depend on the network or on the Warcraft Logs icon server, which gets blocked at times in Spain. If a specialization has no icon of its own, its class icon is used. Ability icons that are downloaded come from Wowhead and Blizzard if Warcraft Logs fails, and on failure they are retried and requested directly from the CDN before showing «?».'],
    ['0.6.9', 'Iconos más fiables: los iconos fijos de la interfaz (inicio, menús, tarjetas) vienen ahora incluidos en el programa. Si el servidor de iconos de Warcraft Logs falla (se bloquea a ratos en España por el fútbol), se usan los de Wowhead y Blizzard, y cada icono se reintenta antes de mostrar el «?». También en la versión web.', 'More reliable icons: the fixed interface icons (home, menus, cards) are now bundled with the program. If the Warcraft Logs icon server fails (it gets blocked at times in Spain because of football matches), Wowhead and Blizzard icons are used, and each icon is retried before showing the «?». Also in the web version.'],
    ['0.6.8', 'Nueva pestaña «Perjuicios» junto a Buffos, como la de Debuffs de Warcraft Logs: lista todos los debuffs de la pelea (en jugadores o en enemigos) con sus aplicaciones y tiempo activo. Elige uno para ver quién lo ha recibido o aplicado, cuánto daño ha hecho y durante cuánto tiempo, con barras y desglose al pasar el ratón. Los jugadores sin especialización conocida muestran el icono de su clase en lugar de «?».', 'New «Debuffs» tab next to Buffs, like Warcraft Logs’ Debuffs tab: it lists every debuff of the fight (on players or on enemies) with its applications and uptime. Pick one to see who received or applied it, how much damage it did and for how long, with bars and a breakdown on hover. Players with no known specialization show their class icon instead of «?».'],
    ['0.6.7', 'Lista de pulls: cada jefe tiene un botón «Todos los trys» que selecciona y combina todos sus intentos, y arriba hay un botón «Todo el log» que combina todos los intentos de todos los jefes. Los iconos de clase vienen ahora incluidos en el programa (los originales de Blizzard) y ya no dependen de descargas. El Top 5 cortes se quita de Resumen: sigue en Informe general (Top 5 cortes de la noche).', 'Pull list: each boss has an «All tries» button that selects and combines all its attempts, and a «Whole log» button at the top combines every attempt of every boss. Class icons are now bundled with the program (Blizzard’s originals) and no longer depend on downloads. Top 5 interrupts is removed from Summary: it stays in General report (Top 5 interrupts of the night).'],
    ['0.6.6', 'Daño recibido: nuevo desplegable con todas las habilidades que han golpeado a la banda y el daño total de cada una. Elige una para ver cuánto daño ha recibido cada jugador de esa habilidad, o deja «Todas las habilidades» para ver el total.', 'Damage taken: new dropdown with every ability that hit the raid and its total damage. Pick one to see how much damage each player took from it, or leave «All abilities» to see the overall total.'],
    ['0.6.5', 'Resumen: los iconos de rol (tanque, sanador y DPS) son ahora los originales de Blizzard. Los iconos de clase ya no se quedan en «?» (si la descarga HD falla se usa el respaldo con el nombre bien escrito). Quitado el consumible Aceite del resumen porque no se puede detectar de forma fiable en el log.', 'Summary: the role icons (tank, healer and DPS) are now Blizzard’s originals. Class icons no longer get stuck on «?» (if the HD download fails the fallback now uses the correctly spelled name). Removed the Oil consumable from the summary because it cannot be detected reliably in the log.'],
    ['0.6.4', 'Arreglado el texto de los pulls de la barra lateral, que salía con código en lugar de «Try 1 · 12,0 %». Los iconos de las specs y habilidades ya no se quedan en «?»: las descargas tienen límite de tiempo para no bloquearse y los iconos que fallan se reintentan solos.', 'Fixed the pull text in the sidebar, which showed code instead of «Try 1 · 12.0 %». Spec and ability icons no longer get stuck on «?»: downloads have a time limit so they cannot hang, and icons that fail retry by themselves.'],
    ['0.6.3', 'Quitado el nombre de la spec junto al nombre en todo el programa (queda el icono). Todas las barras (daño, sanación, daño recibido, escudos, daño a enemigos…) usan el color de la clase de cada jugador, y rojo cuando el daño lo hace un boss o un add. Al pasar el ratón por una barra se muestra el daño o la sanación de cada habilidad de esa persona, como en Warcraft Logs.', 'Removed the spec name next to names across the program (the icon remains). All bars (damage, healing, damage taken, shields, damage to enemies…) use each player’s class color, and red when the damage comes from a boss or an add. Hovering a bar shows the damage or healing of each of that person’s abilities, like Warcraft Logs.'],
    ['0.6.2', 'Detector de PI rehecho: cada fila muestra con claridad quién dio la Infusión de poder (icono de su spec y nombre en el color de su clase), una flecha con el icono del PI y quién la recibió, con el minuto, el daño con PI y el DPS. Quitada la columna de duración.', 'Rebuilt PI detector: each row clearly shows who gave Power Infusion (spec icon and class-colored name), an arrow with the PI icon and who received it, with the minute, damage with PI and DPS. Duration column removed.'],
    ['0.6.1', 'Daño a escudos: un desplegable para elegir el tipo de escudo (Todos, Boss, Aliados o Adds), con el daño total de cada tipo. Los aliados son los jugadores con control mental.', 'Shield damage: a dropdown to pick the shield type (All, Boss, Allies or Adds), showing the total damage of each type. Allies are mind-controlled players.'],
    ['0.6.0', 'Las barras de los pulls usan ahora los colores de los parses de Warcraft Logs pero al revés: cuanto menos vida le queda al jefe, mejor «parse» (gris, verde, azul, morado, naranja, rosa y oro en la kill), y el porcentaje del try sale del mismo color. Botones Actualizar y Combinar pulls más pequeños para que quepan en una sola línea.', 'The pull bars now use the Warcraft Logs parse colors but inverted: the less health the boss has left, the better the «parse» (grey, green, blue, purple, orange, pink and gold on a kill), and the try percentage uses the same color. Smaller Refresh and Combine pulls buttons so they fit on one line.'],
    ['0.5.9', 'Todas las listas con barras (daño, sanación, daño recibido, escudos, mecánicas…) tienen ahora un formato compacto tipo tabla como Warcraft Logs: nombre con el color de la clase, porcentaje, barra, cantidad y DPS en una sola línea, para ver mucho más sin hacer scroll. Nuevos botones «Copiar imagen» y «Guardar PNG» para exportar la lista que estás viendo (con la fase o el rango de tiempo elegido) como imagen y pegarla donde quieras.', 'All bar lists (damage, healing, damage taken, shields, mechanics…) now use a compact table format like Warcraft Logs: class-colored name, percentage, bar, amount and DPS on a single line, so you see much more without scrolling. New «Copy image» and «Save PNG» buttons export the list you are viewing (with the chosen phase or time range) as an image you can paste anywhere.'],
    ['0.5.8', 'Daño a escudos: ahora eliges qué escudos ver con botones por objetivo (el boss, cada add y los jugadores con control mental), que se activan y desactivan a tu gusto; cada escudo y cada jugador muestran su daño y su DPS solo con los escudos que tengas activados.', 'Shield damage: you now choose which shields to see with one button per target (the boss, each add and mind-controlled players), which you can turn on and off; each shield and player shows its damage and DPS only for the shields you have turned on.'],
    ['0.5.7', 'Las barras de Daño a escudos ahora van con el color de la clase de cada jugador y las listas ya no repiten el nombre de la spec junto al nombre (queda solo el icono).', 'The Shield damage bars now use each player’s class color, and the lists no longer repeat the spec name next to the name (only the icon remains).'],
    ['0.5.6', 'Daño a escudos: ahora se puede elegir el tipo de escudo (Todos, Boss o Adds), cada escudo indica si es del boss o de un add y su DPS, y cada jugador muestra el daño por segundo que hizo a los escudos seleccionados. El resumen incluye el DPS total de la raid sobre los escudos.', 'Shield damage: you can now pick the shield type (All, Boss or Adds), each shield says whether it belongs to the boss or an add along with its DPS, and each player shows the damage per second they did to the selected shields. The summary includes the raid total DPS on shields.'],
    ['0.5.5', 'Lista de pulls más clara: barras de vida del jefe más gruesas y con degradado (de rojo a verde según lo cerca que estuvo el kill, y verde completo en las kills). Nuevo botón «Actualizar» arriba de la lista para recargar el log y ver los pulls y kills nuevos si lo estás subiendo en tiempo real.', 'Clearer pull list: thicker boss health bars with a gradient (from red to green depending on how close the kill was, and full green on kills). New «Refresh» button above the list to reload the log and see new pulls and kills while you are uploading it live.'],
    ['0.5.4', 'La tarjeta del parche tiene ahora un efecto animado en los colores del logo de Curse of Ula’tek: borde de energía vil que gira, halo que late detrás del logo y un brillo que recorre la cuenta atrás (se quita con «Animaciones reducidas»). Tipografía igual que NinjaLoot en la barra superior y en toda la app.', 'The patch card now has an animated effect in the colors of the Curse of Ula’tek logo: a spinning fel-energy border, a pulsing glow behind the logo and a shine across the countdown (turned off with «Reduced motion»). Same typography as NinjaLoot in the top bar and across the app.'],
    ['0.5.3', 'Cuando la cuenta atrás del 12.1.5 llega a 0, el parche cambia solo a 12.1.5 en la pantalla de inicio, sin reiniciar la app.', 'When the 12.1.5 countdown reaches 0, the patch switches to 12.1.5 on the home screen by itself, without restarting the app.'],
    ['0.5.2', 'Ficha de personaje: resumen con la misma disposición que Warcraft Logs (dificultad arriba, mejor media a la izquierda, mediana y kills a la derecha, puntos All Star abajo). Al pulsar un jefe se despliegan todos sus logs y al pulsar uno se abre esa run. Nueva métrica «Daño a jefe» junto a DPS y HPS. La cuenta atrás del parche ahora es verde, como su logo.', 'Character page: summary with the same layout as Warcraft Logs (difficulty on top, best average on the left, median and kills on the right, All Star points at the bottom). Clicking a boss expands all its logs and clicking one opens that run. New «Boss Damage» metric next to DPS and HPS. The patch countdown is now green, like its logo.'],
    ['0.5.1', 'Ficha de personaje: junto a cada «Mejor %» sale el icono de la spec con la que se hizo ese parse. Los personajes buscados recientemente se pueden quitar uno a uno (✕) o todos a la vez.', 'Character page: each «Best %» shows the icon of the spec that parse was done with. Recently searched characters can be removed one by one (✕) or all at once.'],
    ['0.5.0', 'Nuevo diseño más sobrio y profesional, como NinjaLoot: grises neutros sin degradados ni brillos, con el turquesa de WipeTime solo en lo importante, y desplegables con el estilo de la app. Al abrir sale directamente el inicio completo. En la ficha de personaje: tabla de rankings más limpia y centrada con el icono de cada jefe, los talentos que lleva ahora (con botón para copiarlos al juego) y el icono de su spec en los resultados del buscador.', 'New, more sober and professional design, like NinjaLoot: neutral greys without gradients or glows, WipeTime teal only for what matters, and dropdowns matching the app. The full home screen shows right away on startup. On the character page: a cleaner, centered rankings table with each boss icon, the talents they use now (with a button to copy them into the game) and their spec icon in the search results.'],
    ['0.4.9', 'WipeTime ya se puede usar también desde el navegador, sin instalar nada: https://kingkhaax.github.io/WipeTime/ (alojada en GitHub Pages). Admite abrir un log con ?report=CÓDIGO&fight=N en la dirección.', 'WipeTime can now also be used from the browser, with nothing to install: https://kingkhaax.github.io/WipeTime/ (hosted on GitHub Pages). A log can be opened with ?report=CODE&fight=N in the address.'],
    ['0.4.8', 'Al abrir WipeTime se resalta la pestaña Inicio (y la sección en la que estés). El botón Personajes abre una pantalla solo con el buscador de personajes. Iconos de la barra superior sin el marco oscuro. Corregido el error «No se pudo consultar GitHub» al buscar actualizaciones: ya no depende del límite de la API de GitHub.', 'Home is highlighted when WipeTime opens (and whichever section you are in). The Characters button opens a screen with just the character search. Top bar icons without the dark frame. Fixed the "Could not reach GitHub" error when checking for updates: it no longer depends on the GitHub API rate limit.'],
    ['0.4.7', 'Actualizaciones más rápidas: si instalaste WipeTime con el Setup, a partir de esta versión solo se descarga lo que ha cambiado, se instala en silencio y el programa se vuelve a abrir solo. Al pulsar la versión de la barra superior se abre Ajustes → Versión.', 'Faster updates: if you installed WipeTime with the Setup, from this version on only what changed is downloaded, it installs silently and the program reopens by itself. Clicking the version in the top bar opens Settings → Version.'],
    ['0.4.6', 'Buscador de personajes rehecho: escribe el nombre (el reino es opcional) y pulsa Intro para ver en una ventana todos los personajes con ese nombre, su reino y la bandera de su país; al pulsar uno se abre su ficha con posiciones, logs por jefe, equipo y modelo, con enlaces a Warcraft Logs, Raider.IO y la armería. Nuevo botón Personajes en la barra superior. La versión de la barra superior se pone en verde si es la última y en rojo si hay una nueva, y se comprueba sola cada pocos minutos.', 'Rebuilt character search: type the name (realm is optional) and press Enter to see in a window every character with that name, its realm and country flag; picking one opens its page with rankings, logs per boss, gear and model, with links to Warcraft Logs, Raider.IO and the armory. New Characters button in the top bar. The version in the top bar turns green when it is the latest and red when a new one exists, and it re-checks by itself every few minutes.'],
    ['0.4.5', 'Nueva tipografía en toda la app: Noto Sans, limpia y profesional como la de Battle.net, incluida en el programa (también en títulos y gráficas). En Ajustes → Apariencia → Fuente hay más opciones: Inter, Roboto, Open Sans, Montserrat, Poppins, Barlow, Exo 2, Rajdhani, Lato, Source Sans 3, Bahnschrift y Expressway (esta usa la que tengas instalada).', 'New typography across the app: Noto Sans, clean and professional like Battle.net’s, bundled with the program (also in titles and charts). Settings → Appearance → Font has more choices: Inter, Roboto, Open Sans, Montserrat, Poppins, Barlow, Exo 2, Rajdhani, Lato, Source Sans 3, Bahnschrift and Expressway (which uses the one you have installed).'],
    ['0.4.4', 'Actualización con un solo botón en Ajustes → Versión: comprueba, descarga, instala y reabre WipeTime sin escribir ninguna dirección de GitHub.', 'One-button update in Settings → Version: it checks, downloads, installs and reopens WipeTime without typing any GitHub address.'],
    ['0.4.3', 'Servidor intermedio movido a Vercel: WipeTime vuelve a funcionar sin claves propias incluso durante los bloqueos de IPs de Cloudflare por los partidos de fútbol.', 'Intermediate server moved to Vercel: WipeTime works again without your own keys even during the Cloudflare IP blocks caused by football matches.'],
    ['0.4.2', 'Nueva ficha de personaje (Buscar personaje en el inicio): posiciones mundial, de región y de reino, tabla por jefe, parche y dificultad, puntuación de Mítica+, equipo y modelo en vivo, botón Actualizar y días sin actualizar el equipo; la armería muestra el modelo del personaje, sin hueco de mano izquierda si lleva arma a dos manos y con los números de las estadísticas; guilds y personajes se registran a mano sin iniciar sesión; fuera las pestañas de credenciales de Ajustes.', 'New character page (Find a character on the home screen): world, region and realm rankings, per-boss table, patch and difficulty, Mythic+ score, live gear and model, Update button and days since the gear was last updated; the armory shows the character model, no off-hand slot with a two-handed weapon and the stat numbers; guilds and characters are registered by hand without signing in; credential tabs removed from Settings.'],
    ['0.4.1', 'Botón «Idiomas» con español, inglés, alemán y francés (el idioma en uso va resaltado); al compararte con los mejores salen su nombre y reino en lugar de Top 1, 2, 3 (con soporte de caracteres chinos, coreanos y cirílicos) y el ranking se pide siempre en vivo; en tu perfil, al pulsar un personaje se despliega su armería con equipo y estadísticas en número y %; iconos de la barra superior sin el aro interior.', 'New «Languages» button with Spanish, English, German and French (the language in use is highlighted); when you compare with the best, their name and realm replace Top 1, 2, 3 (with Chinese, Korean and Cyrillic character support) and the ranking is always fetched live; in your profile, clicking a character opens its armory with gear and stats as numbers and %; top-bar icons without the inner ring.'],
    ['0.4.0', 'Logo oficial de Battle.net en Acerca de.', 'Official Battle.net logo in About.'],
    ['0.3.9', 'Carga mucho más rápida: caché en disco de los datos de Warcraft Logs (reabrir un log o un replay es casi instantáneo), eventos del replay y de los análisis descargados en paralelo, plantillas de guild precargadas y cachés de guild de 24 h. Botón para vaciar la caché en Ajustes → Datos. Contacto de Discord y del icono de Battle.net en Acerca de.', 'Much faster loading: on-disk cache of Warcraft Logs data (reopening a log or replay is almost instant), replay and analysis events downloaded in parallel, preloaded guild rosters and 24 h guild caches. Button to clear the cache in Settings → Data. Discord and Battle.net contact in About.'],
    ['0.3.8', 'El creador del instalador pasa a ser sr.kitkat; Acerca de con Battle.net (KitKat#21202) y Discord más abajo; quitado el campo Mi personaje de Ajustes.', 'Installer publisher is now sr.kitkat; About with Battle.net (KitKat#21202) and Discord lower; removed the My character field from Settings.'],
    ['0.3.7', 'Ranking de guild con clasificación por Daño, Sanación o Daño al jefe.', 'Guild ranking with Damage, Healing or Boss damage classification.'],
    ['0.3.6', 'El programa pasa a llamarse WipeTime (tus datos y ajustes se conservan); el desplegable de tu guild sale justo debajo de ella; Clasificaciones en tres ventanas (DPS, tanques, sanadores) por daño, sanación o daño al jefe, con parse y parse por nivel de objeto; "No estoy en el log" arriba del todo y solo con los jugadores del log; Replay solo en raids, con zoom y arrastre; sin Buffos por jugador; iconos reales e inglés en la guía de mecánicas; servidor intermedio opcional para no pedir claves.', 'The program is now called WipeTime (your data and settings are kept); your guild dropdown shows right under it; Rankings in three windows (DPS, tanks, healers) by damage, healing or boss damage, with parse and item-level parse; "I am not in the log" at the very top and only with the players of the log; Replay only for raids, with zoom and drag; no Buffs per player; real icons and English in the mechanics guide; optional proxy server so no keys are asked.'],
    ['0.2.8', 'Pestañas reordenadas por importancia (Informe general primero, luego Resumen), nueva pestaña Daño evitable, Mecánicas solo con la guía, buffos de banda por clase dentro de Buffos con la barra siempre en el mismo sitio, Resumen del intento traducido, orden por parse en Daño y Sanación, "Nivel de objeto", quitado el enlace wipetime:// de Exportar.', 'Tabs reordered by importance (General report first, then Summary), new Avoidable damage tab, Mechanics only shows the guide, raid buffs by class inside Buffs with the bar always in the same place, translated Fight overview, parse sorting in Damage and Healing, "Item level", removed the wipetime:// link from Export.'],
    ['0.2.7', 'Prepoti: si el buff ya estaba activo al empezar el pull se cuenta en 0:00; se registra el uso de la piedra de salud.', 'Prepot: if the buff was already active when the pull started it counts at 0:00; healthstone usage is tracked.'],
    ['0.2.6', 'Resumen: al hacer clic en un jugador se abre su equipo (como la armería) y los talentos que usó en ese jefe.', 'Summary: clicking a player opens their gear (armory style) and the talents used on that boss.'],
    ['0.2.5', 'Iconos de rol PvP originales, icono de spec en lugar del punto y tooltip con la pieza exacta sin encantar.', 'Original PvP role icons, spec icon instead of the dot and a tooltip with the exact unenchanted piece.'],
    ['0.2.4', 'Acerca de rediseñado (texto, España, Discord) y "Color de botones" en Apariencia.', 'Redesigned About (text, Spain, Discord) and "Button color" in Appearance.'],
    ['0.2.3', 'Soporte opcional para credenciales incluidas en el programa.', 'Optional support for credentials bundled with the program.'],
    ['0.2.2', 'Comparar logs: maná del sanador y mitigación/pasivas del tanque.', 'Compare logs: healer mana and tank mitigation/passives.'],
    ['0.2.1', 'Defensivos: registro exacto de quién usó qué, cuándo y sobre quién.', 'Defensives: exact log of who used what, when and on whom.'],
    ['0.2.0', 'Guía de mecánicas con iconos, dificultades y lo importante de cada jefe.', 'Mechanics guide with icons, difficulties and what matters on each boss.'],
    ['0.1.9', 'Pestañas renombradas, sin Progreso y muertes con icono de spec.', 'Renamed tabs, no Progress and deaths with spec icon.'],
    ['0.1.8', 'Replay: buffos y debuffos del jugador, su objetivo y el jefe.', 'Replay: buffs and debuffs of the player, their target and the boss.'],
    ['0.1.7', 'Top 5 de interrupciones en el resumen.', 'Top 5 interrupts in the summary.'],
    ['0.1.6', 'Temporizador del 12.1.5 en cajas.', '12.1.5 countdown in boxes.'],
    ['0.1.5', 'Comparar logs: hay que pulsar Cargar logs tras añadir, quitar o cambiar un log; si un log no carga ya no sale con 0 de daño y sin rotación, se reintenta y se avisa. Habilidades repetidas del analizador.', 'Compare logs: Load logs is required after adding, removing or changing a log; a log that fails to load no longer shows 0 damage and no rotation, it is retried and reported. Duplicate analyzer abilities.'],
    ['0.1.4', 'Iconos de WoW del paquete en lugar de los dibujados (barra superior, roles, menú de exportar, calaveras); ranking mundial real de Raider.IO en Heroico y Normal.', 'WoW icons from the pack instead of drawn ones (top bar, roles, export menu, skulls); real world ranking from Raider.IO on Heroic and Normal.'],
    ['0.1.3', 'Quitar personajes de "Tus personajes" y sección de personajes favoritos.', 'Remove characters from "Your characters" and a favorite characters section.'],
    ['0.1.2', 'Buscar guilds solo por nombre, sin saber el reino.', 'Find guilds by name only, without knowing the realm.'],
    ['0.1.1', 'Retratos de personaje y escudos de guild.', 'Character portraits and guild crests.'],
    ['0.1.0', 'Primera versión: daño, sanación, muertes, buffos, rotación y parses; replay con mapas; analizador y comparador de logs; Resumen, Detalle, Gráficas, Defensivos y Mecánicas con guía por dificultad; Mítica+; informe de la noche con rankings; guilds con Battle.net y ranking por rol; cuenta atrás y contenido del parche 12.1.5; tooltips; iconos de WoW; nueva estética con los colores del logo.', 'First version: damage, healing, deaths, buffs, rotation and parses; replay with maps; log analyzer and comparison; Summary, Detail, Graphs, Defensives and Mechanics with a per-difficulty guide; Mythic+; night report with rankings; guilds with Battle.net and role-based ranking; countdown and content for patch 12.1.5; tooltips; WoW icons; new look with the logo colors.'],
  ];

  const cls = () => (!res || res.error ? '' : res.outdated ? 'bad' : 'ok');
  const canInstall = () => !!(res && res.outdated && res.canInstall);

  function stateHTML() {
    if (!res) return `<span class="muted">${tr('Aún no se ha comprobado.', 'Not checked yet.')}</span>`;
    if (res.error === 'NO_SOURCE') return `<span class="muted">${tr('Configura abajo la fuente de actualizaciones para poder comprobar la última versión.', 'Set the update source below to check for the latest version.')}</span>`;
    if (res.error) return `<span class="bad">${tr('No se pudo comprobar', 'Could not check')}: ${esc(res.error)}</span>`;
    if (res.outdated) return `<span class="bad">${tr(`Versión atrasada · la última es v${esc(res.latest)}`, `Outdated · latest is v${esc(res.latest)}`)}</span>${res.notes ? `<pre class="ver-notes">${esc(res.notes.slice(0, 600))}</pre>` : ''}`;
    return `<span class="ok">${tr('Tienes la versión más reciente', 'You have the latest version')}</span>`;
  }

  function paintBadge() {
    const b = document.getElementById('verBadge');
    if (!b) return;
    b.textContent = `v${version}`;
    b.className = `ver-badge ${cls()}`;
    b.title = !res ? '' : res.error ? '' : res.outdated ? (tr(`Hay una versión nueva: v${res.latest}`, `New version available: v${res.latest}`)) : (tr('Última versión', 'Latest version'));
  }

  async function check(manual) {
    if (!version) version = ((await window.api.appInfo?.()) || {}).version || '';
    const next = await window.api.updateCheck();
    // un fallo puntual de red no borra el último estado conocido (verde o rojo)
    res = next.error && res && !res.error ? res : next;
    lastCheck = Date.now();
    paintBadge();
    refreshOpenPanel();
    if (manual && res.outdated) toast(tr(`Hay una versión nueva: v${res.latest}`, `New version available: v${res.latest}`));
    return res;
  }

  async function install() {
    const btn = document.getElementById('doUpdate');
    const prog = document.getElementById('verProg');
    if (btn) { btn.disabled = true; btn.textContent = tr('Descargando…', 'Downloading…'); }
    if (prog) prog.hidden = false;
    window.api.onUpdateProgress?.((f) => { const i = document.querySelector('#verProg i'); if (i) i.style.width = `${Math.round(f * 100)}%`; });
    const r = await window.api.updateInstall();
    if (r.error) {
      toast((tr('Error al actualizar: ', 'Update failed: ')) + r.error);
      if (btn) { btn.disabled = false; btn.textContent = buttonLabel(); }
    }
  }

  // Un solo botón: comprueba si hay versión nueva y, si la hay, la descarga e instala
  async function updateNow() {
    const btn = document.getElementById('doUpdate');
    if (btn) { btn.disabled = true; btn.textContent = tr('Buscando…', 'Checking…'); }
    const r = await check(false);
    const st = document.getElementById('verState');
    if (st) st.innerHTML = stateHTML();
    if (r.error) { toast(tr('No se pudo comprobar', 'Could not check') + `: ${r.error}`); if (btn) { btn.disabled = false; btn.textContent = buttonLabel(); } return; }
    if (!r.outdated) { toast(tr('Tienes la versión más reciente', 'You have the latest version')); if (btn) { btn.disabled = false; btn.textContent = buttonLabel(); } return; }
    if (!r.canInstall) { toast(tr('Hay una versión nueva, pero no se puede instalar sola', 'A new version exists, but it cannot be installed automatically')); if (btn) { btn.disabled = false; btn.textContent = buttonLabel(); } return; }
    await install();
  }

  const buttonLabel = () => (res?.outdated
    ? tr(`Actualizar a v${res.latest}`, `Update to v${res.latest}`)
    : tr('Buscar e instalar actualización', 'Check and install update'));

  // Si Ajustes → Versión está abierto, repinta el estado y el botón con el resultado más reciente
  function refreshOpenPanel() {
    const st = document.getElementById('verState');
    if (st) st.innerHTML = stateHTML();
    const num = document.querySelector('.ver-num');
    if (num) num.className = `ver-num ${cls()}`;
    const btn = document.getElementById('doUpdate');
    if (btn && !btn.disabled) btn.textContent = buttonLabel();
  }

  async function init() {
    version = ((await window.api.appInfo?.()) || {}).version || '';
    paintBadge();
    if (WCSettings.get('autoUpdateCheck') !== false) check(false);
  }

  // Seguimiento en tiempo real: cada 3 minutos y al volver a la ventana (si han pasado más de 60 s)
  const recheck = () => { if (WCSettings.get('autoUpdateCheck') !== false && Date.now() - lastCheck > 60000) check(false); };
  setInterval(() => { if (WCSettings.get('autoUpdateCheck') !== false) check(false); }, 3 * 60 * 1000);
  window.addEventListener('focus', recheck);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) recheck(); });

  const reset = () => { res = null; paintBadge(); };
  document.addEventListener('DOMContentLoaded', init);
  return { check, install, updateNow, buttonLabel, init, reset, cls, canInstall, stateHTML, CHANGELOG };
})();
